//! Status portraits for the twelve crew captains.
//!
//! The embedded set is original pixel art generated by `tools/crew_originals.py` for this
//! private experiment. A different set can be dropped in without a rebuild: point
//! `SHINA_SPRITES` at a folder containing `<captain>/<Face>.png`, or add
//! `<workspace>/assets/crew` with the same layout. Each captain needs Normal, Happy,
//! Determined, Surprised, Dizzy and Sad. An incomplete set falls back to the embedded
//! artwork instead of failing startup.
//!
//! The embedded captains also have short animation strips (`<Clip>.strip.png`), which
//! `crate::portraits` plays in the sidebar. A drop-in set may add the same four strips; a
//! set without them, or with a strip of the wrong length, keeps static faces.
use rune::{Image, ImageCache, Waker};
use std::{
    env,
    path::{Path, PathBuf},
    sync::Arc,
};

/// How many portraits ship. Saved captains store an index, so new portraits only append.
pub const PORTRAITS: usize = 12;
/// Display names, in the same order as the captain indices used by threads.
/// Portrait names in the captain editor describe the art, not a captain identity.
pub const PORTRAIT_NAMES: [&str; PORTRAITS] = [
    "Copper", "Mint", "Indigo", "Gold", "Navy", "Mustard", "Hood", "Braids", "Mohawk", "Silver",
    "Chrome", "Fox",
];
pub const CAPTAIN_NAMES: [&str; PORTRAITS] = [
    "Ember", "Juniper", "Sable", "Pip", "Bram", "Wren", "Rook", "Nia", "Jett", "Otto", "Bolt",
    "Kit",
];
/// Folder names used by the sprite-set loader.
pub const CAPTAIN_KEYS: [&str; PORTRAITS] = [
    "ember", "juniper", "sable", "pip", "bram", "wren", "rook", "nia", "jett", "otto", "bolt",
    "kit",
];
/// The work each captain is responsible for.
pub const CAPTAIN_ROLES: [&str; PORTRAITS] = [
    "Platform",
    "Release",
    "Support",
    "Research",
    "Operations",
    "Interface",
    "Security",
    "Data",
    "Performance",
    "Review",
    "Automation",
    "Testing",
];
pub const CAPTAIN_ROLE_DETAIL: [&str; PORTRAITS] = [
    "Architecture and implementation",
    "Release planning and validation",
    "Support investigations and fixes",
    "Long-horizon research and refactors",
    "Deploys, incidents and on-call follow-up",
    "Interface polish, layout and accessibility",
    "Security reviews and hardening",
    "Schemas, migrations and data pipelines",
    "Profiling, latency and memory use",
    "Code review and mentoring",
    "CI, build scripts and tooling",
    "Test coverage and flaky failures",
];
const FACE_FILES: [&str; Face::COUNT] =
    ["Normal", "Happy", "Determined", "Surprised", "Dizzy", "Sad"];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Face {
    Normal,
    Happy,
    Determined,
    Surprised,
    Dizzy,
    Sad,
}

impl Face {
    pub const COUNT: usize = Self::Sad.index() + 1;
    pub const fn index(self) -> usize {
        match self {
            Self::Normal => 0,
            Self::Happy => 1,
            Self::Determined => 2,
            Self::Surprised => 3,
            Self::Dizzy => 4,
            Self::Sad => 5,
        }
    }
}

/// A short animation for one status. Frame 0 of every strip is the matching static face.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Clip {
    /// Ready: breathing and a blink, built on Normal.
    Idle,
    /// Working: typing dots and a nod, built on Determined.
    Working,
    /// Needs you: a startled hop, built on Surprised.
    Attention,
    /// Done: one small hop, built on Happy.
    Happy,
}

impl Clip {
    pub const ALL: [Clip; 4] = [Clip::Idle, Clip::Working, Clip::Attention, Clip::Happy];

    /// The clip a status plays, if any. Failed stays on its static face.
    pub fn for_face(face: Face) -> Option<Clip> {
        match face {
            Face::Normal => Some(Clip::Idle),
            Face::Determined => Some(Clip::Working),
            Face::Surprised => Some(Clip::Attention),
            Face::Happy => Some(Clip::Happy),
            Face::Dizzy | Face::Sad => None,
        }
    }

    pub fn index(self) -> usize {
        self as usize
    }

    fn file(self) -> &'static str {
        match self {
            Clip::Idle => "Idle",
            Clip::Working => "Working",
            Clip::Attention => "Attention",
            Clip::Happy => "Happy",
        }
    }

    /// Frames in the strip, as `tools/crew_originals.py` draws them.
    pub fn frames(self) -> usize {
        match self {
            Clip::Happy => 3,
            _ => 4,
        }
    }

    /// (frame, milliseconds) steps. Idle changes about once a second, Working about four times
    /// a second, Attention hops then holds for five seconds, and Happy plays once.
    pub fn timeline(self) -> &'static [(usize, u32)] {
        match self {
            Clip::Idle => &[
                (0, 1700),
                (1, 1400),
                (0, 1600),
                (1, 1400),
                (0, 600),
                (2, 50),
                (3, 90),
                (2, 50),
            ],
            Clip::Working => &[
                (1, 220),
                (2, 220),
                (0, 260),
                (1, 220),
                (2, 220),
                (0, 260),
                (1, 220),
                (2, 220),
                (0, 260),
                (3, 110),
            ],
            Clip::Attention => &[
                (1, 110),
                (2, 90),
                (0, 120),
                (1, 110),
                (2, 90),
                (3, 700),
                (0, 5200),
            ],
            Clip::Happy => &[(1, 120), (2, 100), (0, 120), (1, 120), (2, 100)],
        }
    }

    /// Whether the clip loops. A one-shot clip ends on frame 0 and stays there.
    pub fn repeats(self) -> bool {
        self != Clip::Happy
    }
}

/// One clip's frames as RGBA, ready for `rune::Pixels::set`.
pub struct Strip {
    pub size: u32,
    pub frames: Vec<Vec<u8>>,
}

impl Strip {
    /// Splits a strip of square frames. None unless it has exactly the clip's frame count.
    fn decode(png: &[u8], clip: Clip) -> Option<Self> {
        let sheet = image::load_from_memory(png).ok()?.to_rgba8();
        let size = sheet.height();
        if size == 0 || sheet.width() != size * clip.frames() as u32 {
            return None;
        }
        let frames = (0..clip.frames() as u32)
            .map(|i| {
                image::imageops::crop_imm(&sheet, i * size, 0, size, size)
                    .to_image()
                    .into_raw()
            })
            .collect();
        Some(Self { size, frames })
    }
}

/// Every clip for one captain, or none.
pub type Motion = [Strip; 4];

type Set = [Image; Face::COUNT];

pub struct Artwork {
    crew: [Set; PORTRAITS],
    /// Head crops for tiles of 24 px and below, where the full bust is too small to read.
    small: [Set; PORTRAITS],
    /// Animation strips for full busts. A captain without all four stays static.
    motion: [Option<Motion>; PORTRAITS],
    pub mark: Image,
    /// The same mark with a light badge, for the dark theme.
    pub mark_dark: Image,
    /// KSG Code's Antigravity provider mark, a bitmap rather than an SVG.
    pub antigravity: Image,
}

impl Artwork {
    pub fn load(workspace: &Path) -> Arc<Self> {
        let wake: Waker = Arc::new(|| {});
        let cache = ImageCache::new(wake);
        let root = sprite_root(workspace);
        let mut crew = Vec::with_capacity(PORTRAITS);
        let mut small = Vec::with_capacity(PORTRAITS);
        let mut motion = Vec::with_capacity(PORTRAITS);
        for captain in 0..PORTRAITS {
            let (set, crop, strips) = portraits(&cache, captain, root.as_deref());
            crew.push(set);
            small.push(crop);
            motion.push(strips);
        }
        let (Ok(crew), Ok(small), Ok(motion)) = (
            <[Set; PORTRAITS]>::try_from(crew),
            <[Set; PORTRAITS]>::try_from(small),
            <[Option<Motion>; PORTRAITS]>::try_from(motion),
        ) else {
            unreachable!("one set per portrait");
        };
        let mark_dark = mark(&cache, true);
        let mark = mark(&cache, false);
        let antigravity = provider_mark(
            &cache,
            include_bytes!("../assets/providers/antigravity.png"),
        );
        // Startup only. Decode off-thread before the first frame, including headless fixtures.
        for image in crew
            .iter()
            .chain(&small)
            .flatten()
            .chain([&mark, &mark_dark, &antigravity])
        {
            image.wait().expect("valid crew artwork");
        }
        Arc::new(Self {
            crew,
            small,
            motion,
            mark,
            mark_dark,
            antigravity,
        })
    }

    pub fn face(&self, captain: usize, face: Face) -> &Image {
        &self.crew[captain.min(PORTRAITS - 1)][face.index()]
    }

    /// The head crop for small tiles. Drop-in sets without crops reuse the full bust.
    pub fn small_face(&self, captain: usize, face: Face) -> &Image {
        &self.small[captain.min(PORTRAITS - 1)][face.index()]
    }

    /// A captain's animation strips, if its set has them.
    pub fn motion(&self, captain: usize) -> Option<&Motion> {
        self.motion.get(captain)?.as_ref()
    }
}

/// An explicit drop-in folder wins over the workspace folder. Neither is required.
fn sprite_root(workspace: &Path) -> Option<PathBuf> {
    env::var_os("SHINA_SPRITES")
        .map(PathBuf::from)
        .filter(|path| path.is_dir())
        .or_else(|| {
            let local = workspace.join("assets").join("crew");
            local.is_dir().then_some(local)
        })
}

fn portraits(
    cache: &ImageCache,
    captain: usize,
    root: Option<&Path>,
) -> (Set, Set, Option<Motion>) {
    if let Some((set, small, folder)) = root.and_then(|root| load_set(cache, root, captain)) {
        return (set, small, load_motion(&folder));
    }
    let (set, small) = embedded(cache, captain);
    (set, small, embedded_motion(captain))
}

/// All four strips from a drop-in folder, or none: a partial set would animate some states
/// and not others.
fn load_motion(folder: &Path) -> Option<Motion> {
    let strips: Vec<Strip> = Clip::ALL
        .iter()
        .map(|clip| {
            let png = std::fs::read(folder.join(format!("{}.strip.png", clip.file()))).ok()?;
            Strip::decode(&png, *clip)
        })
        .collect::<Option<_>>()?;
    Motion::try_from(strips).ok()
}

fn embedded_motion(captain: usize) -> Option<Motion> {
    macro_rules! strips {
        ($name:literal) => {
            [
                include_bytes!(concat!("../assets/crew/", $name, "/Idle.strip.png")).as_slice(),
                include_bytes!(concat!("../assets/crew/", $name, "/Working.strip.png")).as_slice(),
                include_bytes!(concat!("../assets/crew/", $name, "/Attention.strip.png"))
                    .as_slice(),
                include_bytes!(concat!("../assets/crew/", $name, "/Happy.strip.png")).as_slice(),
            ]
        };
    }
    let pngs = match captain {
        0 => strips!("ember"),
        1 => strips!("juniper"),
        2 => strips!("sable"),
        3 => strips!("pip"),
        4 => strips!("bram"),
        5 => strips!("wren"),
        6 => strips!("rook"),
        7 => strips!("nia"),
        8 => strips!("jett"),
        9 => strips!("otto"),
        10 => strips!("bolt"),
        _ => strips!("kit"),
    };
    let strips: Vec<Strip> = Clip::ALL
        .iter()
        .zip(pngs)
        .map(|(clip, png)| Strip::decode(png, *clip))
        .collect::<Option<_>>()?;
    Motion::try_from(strips).ok()
}

/// A set is either the named folder or the numeric captain index. All six faces must
/// decode as files before the whole set is accepted.
fn load_set(cache: &ImageCache, root: &Path, captain: usize) -> Option<(Set, Set, PathBuf)> {
    let folders = [
        root.join(CAPTAIN_KEYS[captain]),
        root.join(captain.to_string()),
    ];
    for folder in folders {
        if !folder.is_dir() {
            continue;
        }
        let mut images = Vec::with_capacity(Face::COUNT);
        let mut crops = Vec::with_capacity(Face::COUNT);
        for name in FACE_FILES {
            let bytes = std::fs::read(folder.join(format!("{name}.png"))).ok()?;
            let image = cache.load(bytes);
            image.wait().ok()?;
            // An optional `<Face>.small.png` head crop; otherwise small tiles use the bust.
            let crop = std::fs::read(folder.join(format!("{name}.small.png")))
                .ok()
                .map(|bytes| cache.load(bytes))
                .filter(|crop| crop.wait().is_ok())
                .unwrap_or_else(|| image.clone());
            images.push(image);
            crops.push(crop);
        }
        if let (Ok(set), Ok(small)) = (Set::try_from(images), Set::try_from(crops)) {
            return Some((set, small, folder));
        }
    }
    None
}

fn embedded(cache: &ImageCache, captain: usize) -> (Set, Set) {
    macro_rules! set {
        ($name:literal) => {
            (
                [
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Normal.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Happy.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Determined.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Surprised.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Dizzy.png")).as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Sad.png")).as_slice(),
                    ),
                ],
                [
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Normal.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Happy.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Determined.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Surprised.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Dizzy.small.png"))
                            .as_slice(),
                    ),
                    cache.load(
                        include_bytes!(concat!("../assets/crew/", $name, "/Sad.small.png"))
                            .as_slice(),
                    ),
                ],
            )
        };
    }
    match captain {
        0 => set!("ember"),
        1 => set!("juniper"),
        2 => set!("sable"),
        3 => set!("pip"),
        4 => set!("bram"),
        5 => set!("wren"),
        6 => set!("rook"),
        7 => set!("nia"),
        8 => set!("jett"),
        9 => set!("otto"),
        10 => set!("bolt"),
        _ => set!("kit"),
    }
}

/// A provider mark from PNG bytes.
fn provider_mark(cache: &ImageCache, png: &[u8]) -> Image {
    let image = image::load_from_memory(png)
        .expect("valid provider mark")
        .to_rgba8();
    cache.rgba(image.width(), image.height(), image.into_raw())
}

fn mark(cache: &ImageCache, light: bool) -> Image {
    let image = cache.rgba(
        crate::brand::SIZE as u32,
        crate::brand::SIZE as u32,
        crate::brand::pixels(light),
    );
    image.wait().expect("valid generated crew mark");
    image
}
